            "every_h_left": "{{amount}} ஒவ்வொரு {{recurrence}} மணிநேரமும் · {{remaining_executions}} மீதம்",
            "in_savings_withdrawals_take_3_days_to": "{{text}} {{savingsBalance}} {{currency}} சேமிப்பில். பணமெடுப்புகள் முடிய 3 நாட்கள் ஆகும்.",
            "swapping_pxa_to_pxs_is_instant_the": "PXA வை PXS ஆக மாற்றுவது உடனடி: PXA வின் பாதி உடனே மாற்றப்படும் (5% கட்டணம் கழிக்கப்படும்); மீதிப் பாதி பிணையமாகப் பூட்டப்பட்டு, ~3.5 நாட்களுக்குப் பிறகு அந்த நேரத்தின் விலைக்கு ஏற்பச் சரிசெய்யப்பட்டுத் திரும்பும். PXS ஐ PXA ஆக மாற்றுவதற்குக் கட்டணம் இல்லை; அது ~3.5 நாட்களுக்குப் பிறகு அந்த நேரத்தின் witness-களின் இடைநிலை விலையில் நிறைவடையும்.",
            "pxp_usable_because": "{{text}} பயன்படுத்தக்கூடிய <0>{{overall}}</0> PXP; ஏனெனில் <1>{{borrowed}}</1> கடன் வாங்கப்பட்டது, <2>{{lended}}</2> கடன் கொடுக்கப்பட்டது.",
            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> வழக்கமான 13-வார power-down சுழற்சியைத் தவிர்த்து, Pixa Power ஐ நேரடியாக வேறு கணக்கிற்கு அனுப்ப முடியும். இந்தக் கருவூலம் பல-கையொப்பக் கணக்கு; எந்த ஒற்றை உள்நுழைவாலும் அதன் நிதியை நகர்த்த முடியாது — கீழே உள்ள <strong>மொத்தப் பரிமாற்றம்</strong> ஐப் பயன்படுத்தவும்: ஒவ்வொரு சாவி வைத்திருப்பவரும் ஒரே தொகுப்பில் தனித்தனியாகக் கையொப்பமிட்ட பின், அவை இணைக்கப்பட்டு அனுப்பப்படும்.",
            "the_big_mac_index_is_a_renown": "பிக் மேக் குறியீடு என்பது வாங்கும் சக்தி, பணவீக்கம், நுகர்வோர் விலைக் குறியீட்டைக் கண்காணிக்கும் புகழ்பெற்ற பொருளாதாரக் குறியீடு.",
            "beware_of_spam_and_phishing_links_in": "பரிமாற்ற memo-க்களில் வரும் ஸ்பேம் மற்றும் ஃபிஷிங் இணைப்புகள் குறித்து எச்சரிக்கை. நம்பாத பயனர்களிடமிருந்து வரும் இணைப்புகளைத் திறக்க வேண்டாம். உங்கள் தனிப்பட்ட சாவிகளை எந்த மூன்றாம் தரப்பு இணையதளத்திற்கும் கொடுக்க வேண்டாம். பரிவர்த்தனைகள் பிளாக்செயினில் உறுதிசெய்யப்படும் வரை காட்டப்படாது; இதற்குச் சில நிமிடங்கள் ஆகலாம்.",
            "are_you_sure_you_want_to_power": "{{amount}} PXA ஐ power up செய்யவா? இது திரவ PXA வை ஸ்டேக் செய்யப்பட்ட Pixa Power ஆக மாற்றும்.",
            "are_you_sure_you_want_to_power_2": "{{amount}} PXP ஐ power down செய்யவா? இது 13 வாராந்திரத் தவணைகளில் வழங்கப்படும்.",
            "are_you_sure_you_want_to_swap": "{{amount}} PXA ஐ PXS ஆக மாற்றவா? பாதி உடனே மாற்றப்படும் (5% கட்டணம் கழிக்கப்படும்), PXS உடனடியாக வரவு வைக்கப்படும். மீதிப் பாதி பிணையமாகப் பூட்டப்பட்டு, ~3.5 நாட்களுக்குப் பிறகு அந்த நேரத்தின் PXA விலைக்கு ஏற்பச் சரிசெய்யப்பட்டுத் திரும்பும்; விலை பாதியாகக் குறைந்திருந்தால், எதுவும் திரும்பாது. மாற்றங்களைத் திரும்பப் பெற முடியாது.",
            "are_you_sure_you_want_to_swap_2": "{{amount}} PXS ஐ PXA ஆக மாற்றவா? PXS இப்போதே உங்கள் இருப்பிலிருந்து வெளியேறும்; PXA ~3.5 நாட்களுக்குப் பிறகு அந்த நேரத்தின் witness-களின் இடைநிலை விலையில் வந்து சேரும். கட்டணம் இல்லை. மாற்றங்களைத் திரும்பப் பெற முடியாது.",
            "move_into_savings_you_can_take_it": "{{amount}} {{currency}} ஐ சேமிப்பிற்கு நகர்த்தவா? எப்போது வேண்டுமானாலும் எடுக்கலாம் (பணமெடுப்புகள் முடிய 3 நாட்கள் ஆகும்).",
            "withdraw_from_savings_the_funds_arrive_after": "{{amount}} {{currency}} ஐ சேமிப்பிலிருந்து எடுக்கவா? நிதி 3-நாள் தாமதத்திற்குப் பிறகு வந்து சேரும்.",
            "weekly_rounds_remaining_pxa_per_round": "{{powerDownWeeksRemaining}} வாராந்திரச் சுற்றுகள் மீதம். ஒரு சுற்றுக்கு ~{{_nextPowerDown}} PXA.",
            "cancel_power_down": "Power down-ஐ ரத்து செய்",
