            "strong_multi_signature_treasury_operation_strong": "<strong>பல-கையொப்பக் கருவூலச் செயல்பாடு.</strong> Pixa Power ஐ <0>@{{from}}</0> இலிருந்து ஒரே நேரத்தில் பல பெறுநர்களுக்கு நகர்த்தவும். ஒவ்வொரு இணை கையொப்பமிடுபவரும் அதே கோப்பில் தனித்தனியாகக் கையொப்பமிடுகிறார்; போதுமான கையொப்பங்கள் இணைக்கப்பட்டுப் பரப்பப்பட்ட பின்னரே பரிமாற்றங்கள் நிறைவேறும்.",
