            "pay_for_the_work": "வேலைக்கான ஊதியம்",
            "protocol_emission_reaches_authors_curators_and_witnesses_as": "நெறிமுறை வெளியீடு ஆசிரியர்கள், தொகுப்பாளர்கள், witness-களை PXA ஆக அடைகிறது — உடலுக்கு வலிமை தரும் வேலைக்காக நெட்வொர்க் செலுத்தும் ஊதியம்.",
            "it_is_earned_through_protocol_emission_not": "இது நெறிமுறை வெளியீட்டின் மூலம் ஈட்டப்படுகிறது; எந்த நிறுவனத்தாலும் வழங்கப்படவோ விற்கப்படவோ இல்லை. இதை வைத்திருப்பது பங்கு அல்ல, வைப்பு அல்ல, லாப வாக்குறுதியும் அல்ல; எந்த நிறுவனத்தின் வருவாய் அல்லது சொத்துகள் மீதும் உரிமை தராது. இது கட்டண டோக்கனாக விளம்பரப்படுத்தப்படவில்லை. PXA என்பது வெறுமனே PXP இன் திரவ நிலை என்பதால், PXP ஐ உள்ளடக்கும் அதே FINMA பயன்பாட்டு-டோக்கன் நியாயம் (Nutzungs-Token, 27 மார்ச் 2025, குறிப்பு G01518211) இதற்கும் பொருந்தும் — முழுப் பதிவுக்கு PXP தாளைக் காண்க.",
