            "liquid_to_move_solid_to_govern_one": "நகர்வதற்குத் திரவம், ஆள்வதற்குத் திடம், முழுவதும் ஒரே உடல்.",
            "liquid_by_design_durable_by_consensus": "வடிவமைப்பால் திரவம், ஒருமித்த உடன்பாட்டால் நீடிப்பு.",
            "pxa_is_the_body_0_flowing_0": "PXA என்பது உடல், <0>ஓடும்</0> நிலையில் — முழுப் பொருளாதாரமும் இயங்கும் <1>திரவம்</1>.",
            "pixa_is_one_living_being_and_pxa": "Pixa ஒரே உயிருள்ள இருப்பு; PXA & PXP அதன் <0>உடல்</0> — <1>Atlas</1>, இரு நிலைகளில் ஒரே பொருள். PXA என்பது <2> திரவ நிலை</2>: நீங்கள் அனுப்பவும் வர்த்தகம் செய்யவும் தீர்வு செய்யவும் பயன்படும் குறைந்த-கட்டண ஊடகம்; உணர்வு (PXS) வந்திறங்கும் வடிவமும் இதுவே. Power up செய்தால் இது 1:1 ஆக PXP ஆக <3> உறைகிறது</3>; power down செய்தால் பதின்மூன்று வாரங்களில் மீண்டும் <4> உருகுகிறது</4>. இது நெட்வொர்க் செய்யும் வேலையிலிருந்து ஈட்டப்படுகிறது — எந்த நிறுவனமும் அச்சிடுவதில்லை.",
            "power_up_and_pxa_0_freezes_0": "Power up செய்தால் PXA ஒன்றுக்கு-ஒன்று, உடனடியாக PXP ஆக <0>உறைகிறது</0>. Power down செய்தால் PXP பதின்மூன்று-வார விடுவிப்பில் மீண்டும் PXA ஆக <1>உருகுகிறது</1>. ஒரே பொருள், இரு நிலைகள் — ஒன்றாக அவை <2>Atlas</2>; supra-வின் எடையைத் தாங்கும் உடல்.",
            "no_company_prints_pxa_the_protocol_0": "எந்த நிறுவனமும் PXA அச்சிடுவதில்லை. நெறிமுறை <0>நிலையான, மெதுவாகக் குறையும் அட்டவணையில் அதை உருவாக்கி</0>, உடலுக்கு வலிமை தரும் வேலை செய்பவர்களுக்கு வழங்குகிறது: ஒவ்வொரு பிளாக்கிலும் படைப்பாளர்களும் தொகுப்பாளர்களும் <1>மிகப்பெரிய பங்கை</1> பெறுகிறார்கள்; மீதி, செயினை இயக்கும் witness-களுக்கும் Decentralised Pixa Fund இற்கும் செல்கிறது. வெறுமனே வைத்திருப்பது எதையும் ஈட்டாது — <2>வெகுமதிகள் வேலை செய்வதால் மட்டுமே வருகின்றன</2>.",
            "the_fixed_shares_of_new_emission_within": "புதிய வெளியீட்டின் நிலையான பங்குகள். உள்ளடக்கத்திற்குள், படைப்பாளர்கள் 60%, தொகுப்பாளர்கள் 40% — யார் ஈட்டுவது வாக்குகளைப் பொறுத்தது.",
            "pxa_is_the_liquid_equivalent_of_pxp": "PXA என்பது PXP இன் திரவச் சமமானது — இதற்குத் தனி வகைப்பாடு இல்லை; Pixagram SA மீது உரிமையும் இல்லை."
