            "pxp_is_the_body_0_at_rest": "PXP என்பது உடல், <0>ஓய்வில்</0> — <1>எடை</1>, மற்றும் <2>குரல்</2>.",
            "pixa_is_one_living_being_and_pxa": "Pixa ஒரே உயிருள்ள இருப்பு; PXA & PXP அதன் <0>உடல்</0> — <1>Atlas</1>, இரு நிலைகளில் ஒரே பொருள். PXP என்பது <2> திட நிலை</2>: இருப்பிற்கு <3> எடையையும்</3> (ஆளுகை) கட்டணமில்லா அலைவரிசையையும் தர 1:1 ஆக உறைந்த PXA. <4>மனதைக்</4> குறிவைக்கும் நங்கூரமும் இதுவே — witness-கள் ஸ்டேக் செய்யப்பட்ட PXP ஆல் தேர்ந்தெடுக்கப்படுகிறார்கள்; எனவே மனம் என்பது உடல் தன்னைப் பற்றித் தானே உருவாக்குவது. விரும்பும் போது, எந்தத் தரப்பும் மாற்ற முடியாத பதின்மூன்று-வார விடுவிப்பில், மீண்டும் திரவ PXA ஆக உருக்கலாம்.",
            "pxp_is_pxa_0_frozen_solid_0": "PXP என்பது <0>திடமாக உறைந்த</0> PXA — உடலுக்கு எடையும் குரலும் தர ஒன்றுக்கு-ஒன்று ஸ்டேக் செய்யப்பட்டது. <1>உருக்கினால்</1> பதின்மூன்று-வார விடுவிப்பில் மீண்டும் திரவ PXA ஆகத் திரும்பும். ஒரே பொருள், இரு நிலைகள்; ஒன்றாக அவை <2>Atlas</2>.",
            "staking_is_not_idle_it_buys_four": "ஸ்டேக்கிங் சும்மா இருப்பதல்ல. அது நான்கு விஷயங்களைத் தருகிறது — அவற்றில் ஒன்று அமைதியாக மனதைக் குறிவைக்கிறது.",
            "unstaking_is_gradual_and_fixed_power_down": "அன்ஸ்டேக்கிங் படிப்படியானது, நிலையானது. Power down செய்தால் உங்கள் PXP <0> பதின்மூன்று சம வாராந்திரத் தவணைகளில்</0> மீண்டும் திரவ PXA ஆக உருகும் — சுமார் தொண்ணூற்றொரு நாட்கள். வீதத்தை நெறிமுறை நிர்ணயிக்கிறது; எந்தத் தரப்பும் விரைவாக்கவோ மெதுவாக்கவோ முடியாது.",
            "each_week_another_equal_slice_melts_back": "ஒவ்வொரு வாரமும் மற்றொரு சம பகுதி திரவ PXA ஆக உருகும்; உங்கள் இருப்பு 100% நோக்கி சீரான, முன்கணிக்கக்கூடிய ஏற்றத்தில் செலவிடத்தக்கதாகும். அட்டவணையின் விளக்கம் மட்டுமே, நேரடித் தரவு அல்ல.",
