            "unknown_not_in_current_session": "தெரியவில்லை — தற்போதைய அமர்வில் இல்லை",
            "not_available": "கிடைக்கவில்லை",
            "please_choose_a_recovery_account": "மீட்புக் கணக்கைத் தேர்ந்தெடுக்கவும்.",
            "you_cannot_set_your_own_account": "உங்கள் சொந்தக் கணக்கை மீட்புக் கணக்காக அமைக்க முடியாது.",
            "this_is_already_your_current_recovery": "இது ஏற்கனவே உங்கள் தற்போதைய மீட்புக் கணக்கு. வேறு கணக்கைத் தேர்ந்தெடுக்கவும், அல்லது நிலுவையிலுள்ள கோரிக்கையை ரத்து செய்ய இதே மதிப்பைப் பயன்படுத்தவும்.",
            "could_not_verify_the_recovery_account": "மீட்புக் கணக்கை சரிபார்க்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
            "owner_key_required_to_change_recovery": "மீட்புக் கணக்கை மாற்ற Owner விசை தேவை.",
            "could_not_change_recovery_account": "மீட்புக் கணக்கை மாற்ற முடியவில்லை: {{message}}",
            "enter_a_recovery_account": "மீட்புக் கணக்கை உள்ளிடவும்",
