            "same_as_current_recovery_account": "தற்போதைய மீட்புக் கணக்கே",
            "working": "செயலில்...",
            "request_change": "மாற்றத்தைக் கோரு",
            "click_the_icon_to_generate_a": "புதிய சீட் சொற்றொடரை உருவாக்க + ஐகானைக் கிளிக் செய்யவும்",
            "generate_or_enter_a_valid_seed": "முதலில் செல்லுபடியான சீட் சொற்றொடரை உருவாக்கவும் அல்லது உள்ளிடவும்",
            "i_downloaded_the_document": "ஆவணத்தைப் பதிவிறக்கிவிட்டேன்",
            "download_the_document_and_acknowledge": "ஆவணத்தைப் பதிவிறக்கி உறுதிப்படுத்தவும்",
            "tick_the_box_above_to_download": "ஆவணத்தைப் பதிவிறக்கி தொடர, மேலே உள்ள பெட்டியில் டிக் செய்யவும்",
