            "marks_the_post_as_deleted_in_its": "இடுகையை அதன் மீத்தரவில் நீக்கப்பட்டதாகக் குறிக்கிறது: எல்லா ஊட்டங்கள், சுயவிவரம், சமூகப் பக்கங்களிலிருந்தும் மறைந்துவிடும். மீளத்தக்கது — மீத்தரவுக் கொடி மட்டுமே தொடப்படும். குறிச்சொல் எதுவும் சேர்க்கப்படாததால், நீக்கப்பட்ட இடுகைகளை உலாவ முடியாது.",
            "erase_the_artwork_content_itself_the_post": "கலைப்படைப்பு உள்ளடக்கத்தையே (இடுகை உடல்) அழிக்கவும். படம் ஆன்-செயினில் மாற்றப்படும்; இங்கிருந்து மீட்டெடுக்க முடியாது — பிளாக் வரலாறு மட்டுமே பழைய பதிப்பை வைத்திருக்கும். இடுகை நீக்கப்பட்டதாகக் குறிக்கப்படும்.",
            "the_post_is_marked_as_deleted_in": "இடுகை அதன் மீத்தரவில் நீக்கப்பட்டதாகக் குறிக்கப்பட்டு, எல்லா ஊட்டங்கள், சுயவிவரம், சமூகப் பக்கங்களிலிருந்தும் மறைந்துவிடும்.",
