            "located_in_monaco": "மொனாக்கோவில் அமைந்துள்ளது",
            "tx": "%n {{{_plurals.transaction}}}",
            "pixa_supra_should_never_surpass_30_of": "Pixa Supra ஒருபோதும் Pixa மூலதனத்தின் 30% ஐ மீறக்கூடாது.",
            "pixasupra_is_a_type_of_token_which": "PixaSupra என்பது <0>உண்மைப்-பொருள் வாங்கும் சக்தியின் உலகளாவிய வாசிப்பை</0> இலக்காகக் கொண்ட oracle-குறிப்பிடப்பட்ட supracoin. நெறிமுறை எந்த எண்ணையும் காப்பதில்லை; பிணையம் தாங்கக்கூடியதைத் தீர்வு வழங்குகிறது.",
            "the_price_feed_for_the_pixasupra_versus": "PixaSupra க்கும் Pixa க்குமான விலை ஊட்டம் சுமார் 1:57. நாணயங்களுக்கிடையே ஊக்கத்தைச் சமன்செய்ய விலை ஊட்டம் பயன்படுகிறது. PixaSupra மற்றும் Pixa சமநிலையை நாடுகின்றன: oracle-குறிப்பிடப்பட்டதை விட <b>3.3x அதிக</b> திரவ டோக்கன் இருக்க வேண்டும்; இதனால் PixaSupra, Pixa மூலதனத்தின் 30% க்குக் கீழே இருக்கும். அதாவது வழங்கலைச் சரிசெய்ய இப்போது <b>3.7x</b> வரம்பு உள்ளது: Pixa விலை அந்த அளவு வீழ்ந்தால், மதிப்புக் கழிவு விதி பொருந்தும்.",
            "based_on_the_price_feed_1_57": "விலை ஊட்டம் (1:57) மற்றும் PixaSupra (பெரும்பாலும் பிக் மேக் குறியீடு போன்றது) அடிப்படையில், ஒரு pixa டோக்கனின் சராசரி விலை சுமார் 10 US சென்ட்கள்.",
            "similar_to_most_stablecoin_its_algorithms_requir": "திசை திருத்தம் ஒரு இயக்குநரின் கை நெம்புகோலில் இல்லை: witness-கள் விலை ஊட்டத்தையும் நெறிமுறை அளபுருக்களையும் ஒருமித்த உடன்பாட்டால் வாக்களிக்கிறார்கள்; நியாயமான APR, நீண்ட-கால ஸ்டேக்கிங்கை வெகுமதிக்கும் அதே வேளை, அமைப்பை அந்த ஊட்டத்தைப் பின்பற்ற அனுமதிக்கிறது.",
            "the_blockchain_can_emit_various_ratio_of": "பிளாக்செயின் PixaSupra vs Pixa பல்வேறு விகிதங்களில் வெளியிட முடியும். PixaSupra, oracle-குறிப்பிடப்பட்ட விகிதத்தில் Pixa ஆக மாறுவதால், நிலுவை PixaSupra, Pixa மூலதனத்துடன் ஒப்பிட்டு எடைபோடப்படுகிறது.",
            "so_the_price_of_pixa_could_drop": "எனவே Pixa Supra மாற்றங்களுக்கு \"மதிப்புக் கழிவு\" பொருந்துவதற்கு முன் Pixa விலை 3.7x வீழலாம். புதிய Pixa Supra அச்சிடுதல் அதற்கு முன்பே நிற்கிறது — அது Pixa மூலதனத்தின் 20% ஐத் தாண்டியவுடன்.",
            "the_blockchain_produces_a_block_every_3": "முதன்மை முனையம் (witness) சுழலும் போது, பிளாக்செயின் ஒவ்வொரு 3 வினாடிக்கும் ஒரு பிளாக் உருவாக்குகிறது.",
            "you_can_choose_the_node_of_the": "நெட்வொர்க்குடன் தொடர்பாட நீங்கள் இணையும் பிளாக்செயின் முனையத்தைத் தேர்வு செய்யலாம்."
