            "your_phone_number_is_verified_for_this_sign": "உங்கள் தொலைபேசி எண் இந்தப் பதிவுக்கு மட்டுமே சரிபார்க்கப்பட்டுள்ளது. நீங்கள் வெளியேறினால், அந்தச் சரிபார்ப்பு காலாவதியாகும் வரை அதை மீண்டும் பயன்படுத்த முடியாது.",
