            "sms_verification_is_not_yet_available_for": "இந்த நாட்டுக்கு SMS சரிபார்ப்பு இன்னும் கிடைக்கவில்லை.",
            "digits_numbers_in_have_at_most_for": "{{digits}} இலக்கங்கள் — {{country}} இல் எண்களுக்கு அதிகபட்சம் {{max}} இலக்கங்கள். வேறு நாட்டுக்கு, அதன் குறியீட்டுடன் (\"+…\") தொடங்கவும் அல்லது பட்டியலிலிருந்து தேர்ந்தெடுக்கவும்.",
            "the_browser_check_could_not_load_if_you": "உலாவிச் சரிபார்ப்பை ஏற்ற முடியவில்லை. நீங்கள் உள்ளடக்கத் தடுப்பானைப் பயன்படுத்தினால், challenges.cloudflare.com ஐ அனுமதித்து மீண்டும் ஏற்றவும்.",
            "checking_number": "எண்ணைச் சரிபார்க்கிறது…",
            "this_phone_number_has_already_been_used": "இந்தத் தொலைபேசி எண் ஏற்கனவே ஒரு கணக்கை உருவாக்கப் பயன்படுத்தப்பட்டுள்ளது.",
            "this_number_has_reached_the_maximum_of": "இந்த எண் அதிகபட்ச வரம்பான {{max}} சரிபார்ப்பு SMS ஐ எட்டிவிட்டது.",
            "an_sms_was_already_sent_to_this_number_the": "இந்த எண்ணுக்கு ஏற்கனவே ஒரு SMS அனுப்பப்பட்டுள்ளது. அடுத்ததை {{date}} முதல் அனுப்பலாம்.",
