            "something_went_wrong_please_try_again": "ஏதோ தவறு நடந்தது. மீண்டும் முயற்சிக்கவும்.",
            "this_phone_is_already_verified_finish_sign": "இந்தத் தொலைபேசி ஏற்கனவே சரிபார்க்கப்பட்டது. நீங்கள் சரிபார்த்த அமர்விலேயே பதிவை நிறைவு செய்யவும், அல்லது அந்தச் சரிபார்ப்பு காலாவதியான பிறகு மீண்டும் முயற்சிக்கவும்.",
            "too_many_verification_requests_from_your": "உங்கள் நெட்வொர்க்கிலிருந்து அளவுக்கு அதிகமான சரிபார்ப்புக் கோரிக்கைகள் வந்துள்ளன. பின்னர் மீண்டும் முயற்சிக்கவும்.",
            "this_phone_number_has_reached_the_maximum": "இந்தத் தொலைபேசி எண் அதிகபட்ச வரம்பான {{max}} சரிபார்ப்பு SMS ஐ எட்டிவிட்டதால், இனி பெற முடியாது.",
            "the_browser_check_did_not_pass_please_try": "உலாவிச் சரிபார்ப்பில் தேர்ச்சி பெறவில்லை. மீண்டும் முயற்சிக்கவும் — தொடர்ந்து தோல்வியடைந்தால், பக்கத்தை மீண்டும் ஏற்றவும் (உள்ளடக்கத் தடுப்பான் இருந்தால் அதில் challenges.cloudflare.com ஐ அனுமதிக்கவும்).",
            "this_version_of_the_app_cannot_pass_the": "இந்தச் செயலிப் பதிப்பால் பதிவுக்கான உலாவிச் சரிபார்ப்பில் தேர்ச்சி பெற முடியாது. சமீபத்திய பதிப்பைப் பெறப் பக்கத்தை மீண்டும் ஏற்றவும்.",
            "the_browser_check_service_is_momentarily": "உலாவிச் சரிபார்ப்புச் சேவை தற்காலிகமாகக் கிடைக்கவில்லை. ஒரு நிமிடத்தில் மீண்டும் முயற்சிக்கவும்.",
            "too_many_verification_requests_right_now": "இப்போது சரிபார்ப்புக் கோரிக்கைகள் அளவுக்கு அதிகமாக உள்ளன. சிறிது நேரம் காத்திருந்து மீண்டும் முயற்சிக்கவும்.",
            "too_many_verification_requests_right_now_2": "இப்போது சரிபார்ப்புக் கோரிக்கைகள் அளவுக்கு அதிகமாக உள்ளன. {{date}} கடந்த பிறகு மீண்டும் முயற்சிக்கவும்.",
            "too_many_verification_requests_right_now_3": "இப்போது சரிபார்ப்புக் கோரிக்கைகள் அளவுக்கு அதிகமாக உள்ளன. பின்னர் மீண்டும் முயற்சிக்கவும்.",
            "sms_verification_is_temporarily_paused": "SMS சரிபார்ப்பு தற்காலிகமாக நிறுத்தப்பட்டுள்ளது. பின்னர் மீண்டும் முயற்சிக்கவும்.",
