            "network_error_could_not_reach_the_account": "நெட்வொர்க் பிழை — கணக்குச் சேவையை அணுக முடியவில்லை.",
            "that_code_expired_send_a_new_one": "அந்தக் குறியீடு காலாவதியானது — புதியதை அனுப்பவும்.",
            "too_many_attempts_request_a_new_code": "அளவுக்கு அதிகமான முயற்சிகள் — புதிய குறியீட்டைக் கோரவும்.",
            "this_phone_is_already_verified_from_another": "இந்தத் தொலைபேசி ஏற்கனவே வேறொரு அமர்வில் சரிபார்க்கப்பட்டது. அங்கேயே நிறைவு செய்யவும், அல்லது அந்தச் சரிபார்ப்பு காலாவதியான பிறகு மீண்டும் முயற்சிக்கவும்.",
            "no_verification_in_progress_for_this_number": "இந்த எண்ணுக்கு எந்தச் சரிபார்ப்பும் நடைபெறவில்லை — முதலில் ஒரு குறியீட்டை அனுப்பவும்.",
            "verification_hiccuped_on_the_server_send_a": "சேவையகத்தில் சரிபார்ப்பில் தற்காலிகக் கோளாறு ஏற்பட்டது — புதிய குறியீட்டை அனுப்பி மீண்டும் முயற்சிக்கவும்.",
            "public_keys_not_found_please_download_the": "பொதுச் சாவிகள் கிடைக்கவில்லை. முதலில் sprout PDF ஐப் பதிவிறக்கவும்.",
            "phone_verification_voucher_missing_go_back": "தொலைபேசிச் சரிபார்ப்புச் சான்று இல்லை. பின்சென்று உங்கள் தொலைபேசியை மீண்டும் சரிபார்க்கவும்.",
            "unknown_error": "அறியப்படாத பிழை",
            "your_phone_verification_expired_go_back_and": "உங்கள் தொலைபேசிச் சரிபார்ப்பு காலாவதியானது. பின்சென்று உங்கள் தொலைபேசியை மீண்டும் சரிபார்க்கவும்.",
            "this_phone_verification_was_already_used_to": "இந்தத் தொலைபேசிச் சரிபார்ப்பு ஏற்கனவே ஒரு கணக்கை உருவாக்கப் பயன்படுத்தப்பட்டது.",
            "an_account_creation_with_this_verification_is": "இந்தச் சரிபார்ப்புடன் ஒரு கணக்கு உருவாக்கம் ஏற்கனவே நடைபெற்று வருகிறது — ஒரு நிமிடம் காத்திருந்து, பின்னர் மீண்டும் முயற்சிக்கவும்.",
            "was_just_taken_on_chain_go_back_and_pick": "@{{username}} இப்போதுதான் ஆன்-செயினில் எடுக்கப்பட்டது. பின்சென்று வேறொரு பெயரைத் தேர்ந்தெடுக்கவும் — உங்கள் தொலைபேசிச் சரிபார்ப்பு இன்னும் செல்லுபடியாகும்.",
            "account_creation_capacity_is_exhausted_for": "கணக்கு உருவாக்கக் கொள்ளளவு தற்போது தீர்ந்துவிட்டது. புதிய இடங்கள் {{date}} இல் திறக்கும் — உங்கள் தொலைபேசிச் சரிபார்ப்பு செல்லுபடியாகவே இருக்கும்.",
            "error_your_phone_verification_is_still_valid": "{{error}} உங்கள் தொலைபேசிச் சரிபார்ப்பு இன்னும் செல்லுபடியாகும் — பின்சென்று சிறிது நேரத்தில் மீண்டும் முயற்சிக்கவும்.",
            "the_network_broadcast_failed": "பரிவர்த்தனையை நெட்வொர்க்கிற்கு ஒளிபரப்ப முடியவில்லை.",
