            "at_genesis_the_pixa_chain_minted_pxa": "ஜெனிசிஸில் Pixa செயின் மூன்று கருவூலக் கணக்குகளுக்கு {{pixa}} PXA மற்றும் {{pxs}} PXS ஐ உருவாக்கியது: {{team}} க்கு {{teamAmount}} PXA, {{company}} க்கு {{companyAmount}} PXA மற்றும் {{dpf}} க்கு {{dpfAmount}} PXS. இந்த மூன்று இருப்புகளே TGE ஒதுக்கீடு; அதன் பிறகு அவை செலுத்திய அனைத்தும் கீழே கணக்கு வாரியாகப் பட்டியலிடப்பட்டுள்ளன.",
            "two_special_accounts": "இரண்டு சிறப்புக் கணக்குகள்",
            "and_are_multi_signature_accounts_restricted_at": "{{team}} மற்றும் {{company}} ஆகியவை நெறிமுறை அளவில் கட்டுப்படுத்தப்பட்ட பல-கையொப்பக் கணக்குகள்: அவை ஸ்டேக் செய்யப்பட்ட பயன்பாட்டு டோக்கனான Pixa Power (PXP) ஐ மட்டுமே பரிமாற்ற முடியும்; திரவ PXA அல்லது PXS ஐ நகர்த்த முடியாது. அவை ஒருபோதும் வாக்களிப்பதில்லை — witness-களுக்கும் இல்லை, முன்மொழிவுகளுக்கும் இல்லை — எனவே ஆளுகையில் அவற்றின் ஸ்டேக்கிற்கு எந்த எடையும் இல்லை.",
            "two_policies": "இரண்டு கொள்கைகள்",
            "is_discretionary_the_team_rewards_contributors": "{{team}} விருப்புரிமைக்கு உட்பட்டது: அணி தனது விருப்பப்படி, அட்டவணையோ உச்சவரம்போ இல்லாமல், பங்களிப்பாளர்களுக்கு PXP இல் வெகுமதி அளிக்கிறது. {{company}} ஒரு நிலையான வழித்தடத்தைப் பின்பற்றுகிறது: அதன் முழு ஒதுக்கீடும் TGE க்குப் பிறகு {{min}} முதல் {{max}} ஆண்டுகளுக்குள் விநியோகிக்கப்பட வேண்டும் — அதற்கு மேலும் இல்லை, குறைவும் இல்லை. நேரடி விற்பனைகளும், PXP ஐ power-down செய்து பரிமாற்றகங்களுக்கான திரவ PXA ஆக மாற்றும் இயக்கக் கணக்கிற்கான பரிமாற்றங்களும் விநியோகமாகக் கணக்கிடப்படுகின்றன.",
            "the_decentralized_pixa_fund": "Decentralized Pixa Fund",
            "is_the_decentralized_pixa_fund_it_has": "{{dpf}} என்பது Decentralized Pixa Fund. அதற்கு தனிப்பட்ட சாவிகள் இல்லை, எனவே யாரும் அதன் சார்பாகக் கையொப்பமிட முடியாது: அதன் PXS, பங்குதாரர்களின் வாக்கால் அங்கீகரிக்கப்பட்ட முன்மொழிவுகள் வழியாக மட்டுமே, ஒரு நாளைக்கு இருப்பில் அதிகபட்சம் 1/{{divider}} வரை வெளியேறுகிறது; மேலும் நிதியம் செயினின் பணவீக்கத்தில் தனது பங்கைத் தொடர்ந்து பெறுகிறது.",
