            "the_team_may_use_these_funds_at": "அணி இந்த நிதிகளைத் தனது விருப்பப்படி — பங்களிப்பாளர்களுக்கு Pixa Power இல் வெகுமதி அளிக்க — அட்டவணையோ தொகை விதியோ இல்லாமல் பயன்படுத்தலாம். ஒரே வரம்புகள் கணக்கிற்கே உரியவை: PXP பரிமாற்றங்கள் மட்டும், வாக்களிப்பு இல்லை.",
            "the_company_treasury_must_be_fully_distributed": "நிறுவனக் கருவூலம் TGE க்குப் பிறகு {{min}} முதல் {{max}} ஆண்டுகளுக்குள் முழுமையாக விநியோகிக்கப்பட வேண்டும் — அதற்கு மேலும் இல்லை, குறைவும் இல்லை. இதுவே விநியோக வழித்தடம்.",
