            "lift_the_smallest_accounts_as_you_climb": " ஏறும்போது மிகச் சிறிய கணக்குகளையும் தூக்கிவிடு, ஏனெனில் இன்றைய சிறுமீன் நாளைய ஆசான்.",
            "but_treat_it_sometimes_as_an_impostor": " ஆனால் சில வேளைகளில் அதை ஏமாற்றுக்காரியாகக் கருது — எப்போதும் நீதியுடன் இரு. கூட்டம் விரும்புவது எப்போதும் சிறந்ததல்ல; உன் நீதிபதியாக நீயே இரு.",
            "to_dislike_is_your_right_and_to": " பிடிக்காமல் இருப்பது உன் உரிமை, தீர்ப்பளிப்பது தணிக்கை அல்ல; உன்னை அசைக்காத எந்தப் படைப்பிற்கும் கீழ்வாக்களி அல்லது கடந்து செல்.",
            "a_community_is_known_by_how_it": " ஒரு சமூகம் பலவீனரைக் காக்கும் விதத்தால் அறியப்படுகிறது; உன் வலிமையைப் படைப்பின் பக்கம் திருப்பு, ஒருபோதும் மற்றொருவருக்கு எதிராக அல்ல.",
            "let_every_tool_serve_the_creator_and": " ஒவ்வொரு கருவியும் படைப்பாளிக்குச் சேவை செய்யட்டும், ஒருபோதும் அவர் இடத்தைப் பிடிக்க வேண்டாம்.",
