            "vote_concentration_info": "Witness-களுக்கு வாக்களிக்கும் ஸ்டேக்கில் மிகப்பெரிய வாக்களிக்கும் தரப்புகள் வைத்திருக்கும் பங்கு; ஒரு கணக்குக்கு proxy செய்யப்பட்ட ஸ்டேக் அந்தக் கணக்குடனேயே கணக்கிடப்படும். 50% கோட்டைத் தாண்டத் தேவையான தரப்புகள் எவ்வளவு குறைவோ, அட்டவணையைக் கைப்பற்றுவது அவ்வளவு எளிது.",
