            "interest_votes_info": "சேமிப்பில் உள்ள PXS-க்குச் செலுத்தப்படும் வட்டி, தேர்ந்தெடுக்கப்பட்ட witness-கள் வாக்களிக்கும் விகிதங்களின் இடைநிலை ஆகும். ஒவ்வொரு பட்டியும் ஒரு witness-இன் வாக்கு; கோடு இடைநிலையைக் காட்டுகிறது.",
