            "feeds_versions_info": "தேர்ந்தெடுக்கப்பட்ட ஒவ்வொரு witness-உம் கடைசியாக விலைத் தரவை எவ்வளவு நேரத்துக்கு முன் வெளியிட்டார் என்பதும், பின்னர் கையொப்ப விசை உள்ள witness-கள் இயக்கும் மென்பொருளும் அவர்கள் வாக்களிக்கும் ஹார்ட்ஃபோர்க்கும்.",
