            "s_witness_activity": "Witness-கள், கடந்த 30 நாட்கள்",
            "s_witness_activity_desc": "பிளாக் உற்பத்தி, அட்டவணையை நகர்த்தும் வாக்குகள், உற்பத்தியாளர்கள் ஈட்டுவது, வாக்கு எவ்வளவு குவிந்துள்ளது, witness-கள் எதை அமைக்கிறார்கள், எதை இயக்குகிறார்கள்.",
            "s_reports": "அறிக்கைகள்",
            "s_reports_desc": "ஒவ்வொரு நாள், வாரம், மாதத்துக்குமான witness அறிக்கைகள், முந்தைய காலத்துடன் ஒப்பிட்டு, இடுகையிடத் தயாராக.",
            "witness_reports": "Witness அறிக்கைகள்",
            "witness_reports_info": "ஒரு காலம் முடியும்போது Tower அறிக்கையை எழுதுகிறது; நடப்புக் காலத்துக்கானது கோரிக்கையின் பேரில் உருவாக்கப்படுகிறது. தரவரிசை, வாக்குகள், உற்பத்தி, தவறிய பிளாக்குகள், அளவுருக்கள், விலைத் தரவுகள், பதிப்புகள், முந்தைய காலத்துடன் ஒப்பிட்டு.",
            "block_production_heat_info": "அட்டவணையிடப்பட்ட இடங்களுக்கு எதிராக உற்பத்தியான பிளாக்குகள். ஒவ்வொரு வரிசையும் பிளாக்குகளைத் தவறவிட்ட ஒரு witness, ஒவ்வொரு கட்டமும் ஒரு நாள்: எவ்வளவு வெளிர்வாக இருக்கிறதோ, அந்த நாளில் அது அவ்வளவு அதிக இடங்களைக் காலியாக விட்டது (வெற்றுக் கட்டம்: அந்த நாளில் இடம் இல்லை). தவறிய இடம் இழக்கப்படுவதில்லை: செயின் 3 வினாடிகள் கழித்து அடுத்த witness-உடன் தொடர்கிறது.",
