            "rewards_flow_info": "உள்ளடக்க வெகுமதிகள் வெகுமதித் தொகுப்பிலிருந்து வந்து வாக்குகளால் பகிரப்படுகின்றன; உற்பத்தியாளர் வெகுமதிகள் உற்பத்தியான ஒவ்வொரு பிளாக்குக்கும் வழங்கப்படுகின்றன. இடப்புறமுள்ள தொகுதி, எல்லா வெகுமதிகளிலும் ஒவ்வொரு மூலத்தின் பங்கைக் காட்டுகிறது. தற்போதைய விகிதத்தில் ஸ்டேக் (VESTS), இடைநிலைத் தரவில் PXS, திரவ PIXA உள்ளபடி. பரவலாக்கப்பட்ட Pixa Fund-இன் கொடுப்பனவுகள் Control Tower-இல் உள்ளன.",
