            "0_pixagram_0_is_pioneering_the_future": "<0>Pixagram</0> பிளாக்செயின் தொழில்நுட்பத்தால் டிஜிட்டல் கலை உரிமையின் எதிர்காலத்தில் முன்னோடியாக உள்ளது. உலகெங்கிலுமிருந்து வந்த நிபுணர்கள் குழு, பல அதிகார வரம்புகளை உள்ளடக்கிய பரவலாக்கப்பட்ட சூழலை உருவாக்கியது — <1> பிக்சல் கலை பிளாக்செயின் நிலைத்தன்மையைச் சந்திக்கும்</1> புரட்சிகர சமூக ஊடகத் தளம்.",
            "our_mission_is_to_empower_creators_with": "படைப்பாளர்களுக்கு உண்மையான உரிமையும் நியாயமான வருவாயாக்கமும் தருவதே எங்கள் நோக்கம். வருவாயில் 97% ஐத் தமக்கே வைத்துக்கொள்ளும் பாரம்பரியத் தளங்கள் போலன்றி, NFT விற்பனை, tipping, எங்கள் புத்தாக்க <0>Proof-of-Brain ஒருமித்த இயங்குமுறை</0> வழியாகப் படைப்பாளர்கள் நேரடியாக ஈட்ட Pixagram உதவுகிறது. ஒவ்வொரு பிக்சலும் ஆன்-செயினில் சேமிக்கப்பட்டு, உங்கள் கலை தலைமுறைகளுக்குப் பாதுகாக்கப்படுகிறது.",
