            "in_no_event_shall_pixagram_sa_be": "மென்பொருளிலிருந்தோ, மென்பொருள் அல்லது அதன் பயன்பாடு அல்லது மென்பொருளுடனான பிற செயல்பாடுகள் தொடர்பாகவோ எழும் எந்தக் கோரிக்கை, சேதங்கள் அல்லது பிற பொறுப்புக்கும் எந்தச் சூழ்நிலையிலும் PIXAGRAM SA பொறுப்பாகாது.",
            "permission_is_granted_without_charge_to_any": "இந்த மென்பொருளின் நகலையும் அதனுடன் தொடர்புடைய ஆவணக் கோப்புகளையும் (\"மென்பொருள்\") பெறும் எந்தத் தரப்புக்கும், மென்பொருளைக் கட்டுப்பாடின்றிக் கையாளக் கட்டணமின்றி அனுமதி வழங்கப்படுகிறது. இதில், மென்பொருளின் நகல்களைப் பயன்படுத்த, நகலெடுக்க, மாற்றியமைக்க, இணைக்க, வெளியிட, விநியோகிக்க, துணை உரிமம் வழங்க மற்றும்/அல்லது விற்பனை செய்வதற்கான உரிமைகளும், மென்பொருள் வழங்கப்படும் தனிநபர்களையும் அவ்வாறு செய்ய அனுமதிப்பதற்கான உரிமையும் அடங்கும்; இவை பின்வரும் நிபந்தனைகளுக்கு உட்பட்டவை: மேற்கண்ட பதிப்புரிமை அறிவிப்பும் இந்த அனுமதி அறிவிப்பும் மென்பொருளின் அனைத்து நகல்களிலும் அல்லது கணிசமான பகுதிகளிலும் சேர்க்கப்பட வேண்டும்."
