            "royalty_percentage_is_required_and_must_be": "ராயல்டி சதவீதம் தேவை; அது 0 முதல் 100 வரை இருக்க வேண்டும்",
            "requires_to_be_enabled": "\"{{right}}\" க்கு \"{{parent}}\" இயக்கப்பட்டிருக்க வேண்டும்",
            "percentage_you_ll_receive_on_secondary_sales": "இரண்டாம்நிலை விற்பனைகளில் நீங்கள் பெறும் சதவீதம் (0-100)"
