            "some_figures_could_not_be_valued_in": "சில எண்ணிக்கைகளை {{fiat}} இல் மதிப்பிட முடியவில்லை: விலை மூலம் அவற்றுக்கு {{fiat}} விகிதம் எதையும் தரவில்லை. அவை \"{{na}}\" எனக் காட்டப்படுகின்றன (பூஜ்ஜியம் அல்ல); அவற்றை உள்ளடக்கிய ஒவ்வொரு மொத்தமும் முழுமையற்றது. இந்த அறிக்கையைப் பயன்படுத்தும் முன் விலை மூலத்தைச் சரிசெய்யவும்.",
