            "total": "மொத்தம்",
            "pxp_pixa_power_is_pixa_you_have_staked": "PXP (Pixa Power) என்பது நீங்கள் ஸ்டேக் செய்த PIXA. அது இன்னும் உங்களுக்குச் சொந்தமானது; power-down மூலம் (13 வாரங்களில் வழங்கப்படும்) அதை மீண்டும் மாற்றலாம்; எனவே அது அதன் PIXA மதிப்பில் உங்கள் சொத்தின் பகுதியாகும். ஸ்டேக் செய்வதோ மற்றொரு கணக்கிற்கு ஒப்படைப்பதோ அதை நீக்குவதில்லை; பிறர் உங்களுக்கு ஒப்படைத்த PXP உங்களுடையது அல்ல, சேர்க்கப்படவும் இல்லை.",
