            "summary_by_type_all_disposals": "வகை வாரியான சுருக்கம். எல்லா அகற்றல்களும் ({{count}}) — பயன்படுத்தப்பட்ட செலவு-அடிப்படைத் தொகுதிகள், வைத்திருப்புக் காலத்துடன் — {{csv}} இல் வரிசை வாரியாக விவரிக்கப்பட்டுள்ளன.",
