            "rewards_paid_in_pxp_are_treated_like": "PXP ஆக (ஸ்டேக் செய்யப்பட்டு) வழங்கப்படும் வெகுமதிகள் திரவ வெகுமதிகளைப் போலவே கையாளப்படுகின்றன: பெற்ற நாளில் அவற்றின் PIXA மதிப்பே கணக்கில் கொள்ளப்படும், பின்னாளைய மூலதன ஆதாயம் அல்ல.",
            "caution_these_values_use_one_snapshot": "எச்சரிக்கை: இந்த மதிப்புகள், ஒவ்வொரு வெகுமதியும் பெறப்பட்ட நாளின் விலையை அல்ல, எல்லாத் தேதிகளுக்கும் ஒரே ஸ்னாப்ஷாட் விலையைப் பயன்படுத்துகின்றன. வருமானம் பெறப்பட்ட நாளிலேயே மதிப்பிடப்பட வேண்டும் — தாக்கல் செய்யும் முன் வரலாற்று விலைகளுடன் மீண்டும் உருவாக்கவும்.",
            "summary_by_type_all_income_events": "வகை வாரியான சுருக்கம். எல்லா வருமான நிகழ்வுகளும் ({{count}}) {{csv}} இல் வரிசை வாரியாக விவரிக்கப்பட்டுள்ளன.",
            "account_movements_fees_savings_staking": "கணக்கு நகர்வுகள் — கட்டணங்கள், சேமிப்பு, ஸ்டேக்கிங் & ஒப்படைப்புகள்",
            "not_taxable_disposals_or_income_proposal_fees": "வரிக்குரிய அகற்றல்களோ வருமானமோ அல்ல. முன்மொழிவுக் கட்டணங்கள் கணக்கிலிருந்து வெளியேறி இருப்புகளைக் குறைக்கின்றன; மாற்றக் கோரிக்கைகள், சேமிப்புப் பணமெடுப்புகள், power நகர்வுகள் ஆகியவை அக நகர்வுகள்; முழுமைக்காகக் காட்டப்படுகின்றன. ஒப்படைப்புகள் வாக்களிக்கும் சக்தியை மட்டுமே இரவல் தருகின்றன — PXP அதன் உரிமையாளரிடமே இருக்கும். ஒவ்வொரு வரிசையின் துல்லியமான நேரமும் (UTC) பரிவர்த்தனை id-யும் அதன் தேதிக்குக் கீழே தோன்றும்.",
