            "showing_the_first_of_movements": "{{total}} நகர்வுகளில் முதல் {{shown}} காட்டப்படுகின்றன. முழுப் பட்டியல் {{csv}} இல் உள்ளது.",
            "every_send_you_made_over_the_period": "இக்காலத்தில் நீங்கள் செய்த ஒவ்வொரு அனுப்பலும், அது எதற்காக என்பதன்படி தொகுக்கப்பட்டு, மொத்தத் தொகையுடனும் பரிமாற்றங்களின் எண்ணிக்கையுடனும். பிறருக்கான கொடுப்பனவுகள் அகற்றல்கள்: அவற்றின் ஆதாயம் பரிவர்த்தனைகள் பிரிவில் கணக்கிடப்பட்டு, உங்கள் அதிகார வரம்பு வரி விதிக்கும் இடத்தில் மட்டுமே வரி விதிக்கப்படும். பிற நோக்கங்கள் குறிப்பிட்டபடி கையாளப்படுகின்றன. உங்கள் நாட்டிற்கான நடைமுறையை ஓர் ஆலோசகருடன் உறுதிப்படுத்தவும்.",
            "payments_to_others": "பிறருக்கான கொடுப்பனவுகள்",
            "col_purpose": "நோக்கம்",
            "col_tax_treatment": "வரி நடைமுறை",
            "col_total_fiat": "மொத்தம் ({{fiat}})",
            "transfers_out_classified_by_purpose": "வெளிச்செல் பரிமாற்றங்கள் — நோக்கத்தின்படி வகைப்படுத்தப்பட்டவை",
            "total_sent_out": "அனுப்பிய மொத்தம்",
            "none_of_these_transfers_is_a_disposal": "இந்தப் பரிமாற்றங்களில் எதுவும் அகற்றல் அல்ல. பரிமாற்ற வாரியான விவரம் {{csv}} இல் உள்ளது.",
            "disposals_among_these_some_taxed": "இந்தப் பரிமாற்றங்களில் அகற்றல்கள்: {{count}}, மதிப்பு {{value}} {{fiat}}; ஆதாயம் பரிவர்த்தனைகள் பிரிவில் கணக்கிடப்பட்டது; அவற்றில் {{taxed}} {{jurisdiction}} இல் வரிக்குரிய ஆதாயத்தை உருவாக்கின. பரிமாற்ற வாரியான விவரம் {{csv}} இல் உள்ளது.",
            "disposals_among_these_none_taxed": "இந்தப் பரிமாற்றங்களில் அகற்றல்கள்: {{count}}, மதிப்பு {{value}} {{fiat}}; ஆதாயம் பரிவர்த்தனைகள் பிரிவில் கணக்கிடப்பட்டது; அவற்றில் எதுவும் {{jurisdiction}} இல் வரிக்குரிய ஆதாயத்தை உருவாக்கவில்லை. பரிமாற்ற வாரியான விவரம் {{csv}} இல் உள்ளது.",
