            "col_out": "வெளியேறியது",
            "col_closing": "இறுதி",
            "opening_balance_total_received_and": "ஒவ்வொரு டோக்கனுக்கும் தொடக்க இருப்பு, இக்காலத்தில் பெற்றதும் அகற்றியதுமான மொத்தம், இறுதி இருப்பு. மேம்பட்டவை பிரிவில் உள்ளிட்ட இருப்புகளைத் தொடக்கம் பிரதிபலிக்கும்.",
            "pxp_quantities_are_rebuilt_from_the": "PXP அளவுகள், மதிப்பீட்டு அடிப்படையில் காட்டப்பட்ட vesting விகிதத்தில் கணக்கு வரலாற்றிலிருந்து மறுகட்டமைக்கப்படுகின்றன. தாக்கல் செய்யும் முன், இறுதி PXP ஐ அதே தேதியில் கணக்கின் ஆன்-செயின் vesting இருப்புடன் ஒப்பிட்டுச் சரிபார்க்கவும் — அவை வேறுபட்டால், ஆன்-செயின் இருப்பையே அறிவிக்க வேண்டும்.",
            "operations_not_booked_claim": "கணக்கு வரலாற்றில் காணப்பட்டவை, ஆனால் மேலுள்ள எண்ணிக்கைகளில் சேர்க்கப்படாத செயல்பாடுகள் — மொத்தம் {{total}}. இவை இருப்பில் தாக்கமில்லா சமூக/ஆளுகைச் செயல்கள், பெறும்போதே கணக்கிடப்பட்ட வருமானம், அல்லது பின்னர் நிறைவேறும்/செயல்படுத்தப்படும்போது தீர்வாகும் நகர்வுகள். வகை வாரியான எண்ணிக்கை:",
            "operations_not_booked_accrual": "கணக்கு வரலாற்றில் காணப்பட்டவை, ஆனால் மேலுள்ள எண்ணிக்கைகளில் சேர்க்கப்படாத செயல்பாடுகள் — மொத்தம் {{total}}. இவை இருப்பில் தாக்கமில்லா சமூக/ஆளுகைச் செயல்கள், வரவு வைக்கப்பட்டபோதே கணக்கிடப்பட்ட வருமானம், அல்லது பின்னர் நிறைவேறும்/செயல்படுத்தப்படும்போது தீர்வாகும் நகர்வுகள். வகை வாரியான எண்ணிக்கை:",
