            "the_fingerprint_is_computed_over_the": "இந்த அறிக்கையின் தரவுத் தொகுப்பின் சுருக்கமான JSON வரிசைப்படுத்தலின் மீது கைரேகை கணக்கிடப்படுகிறது; அது இந்த ஆவணத்தை அதன் CSV, JSON ஏற்றுமதிகளுடன் இணைக்கிறது. இதிலுள்ள எந்த எண்ணிக்கையையும் அந்தக் கோப்புகளிலுள்ள உருப்படி வாரியான விவரத்தில் கண்டறியலாம்.",
