            "deductions_losses_and_exemption": "முன்கொண்டுவரப்பட்ட நட்டங்கள் {{losses}} {{fiat}}; வேறிடத்தில் ஏற்கனவே பயன்படுத்திய விலக்கு {{exemption}} {{fiat}}.",
