            "scope": "வரம்பெல்லை",
            "scope_value": "@{{account}} க்கான தளத்திலுள்ள செயல்பாடு, {{period}}. தளத்திற்கு வெளியிலான நிகழ்வுகள் (வெளிப் பரிமாற்றகங்கள், பிற செயின்கள்) வரம்பெல்லைக்கு வெளியே உள்ளன; அவை தனியாக அறிக்கையிடப்பட வேண்டும்.",
