            "tokens_value": "PIXA (திரவம்; CSV கோப்புகளில் PXA ஆக ஏற்றுமதி செய்யப்படுகிறது), PXS (Pixa Supra), PXP (Pixa Power: ஸ்டேக் செய்யப்பட்ட PIXA, 1 PXP = 1 PIXA).",
