            "assumptions": "அனுமானங்கள்",
            "swiss_annex_title": "அதிகார வரம்பு இணைப்பு — சுவிட்சர்லாந்து (எண்ணிக்கைகள் எங்கே செல்கின்றன)",
            "swiss_annex_note": "சுவிட்சர்லாந்தில் ஒரு தனிப்பட்ட முதலீட்டாளரின் வரிக் கணக்கில் எண்ணிக்கைகள் எவ்வாறு பொருந்துகின்றன. சொற்கள் வழக்கமான கேன்டன் பத்திரப் பட்டியலைப் (Wertschriftenverzeichnis / état des titres) பின்பற்றுகின்றன; உங்கள் கேன்டனின் படிவம் வரிசைகளை வேறு விதமாகப் பெயரிடலாம். இந்த வெகுமதிகளுக்குச் சுவிஸ் மூல வரிப் பிடித்தம் பொருந்தாது; எனவே அவற்றின் வருமானம் மூல வரிப் பிடித்தம் இல்லாத வருமானத்திற்கான நெடுவரிசையில் செல்லும்.",
            "swiss_annex_not_in_chf": "இந்த எண்ணிக்கைகள் {{fiat}} இல் உள்ளன, ஆனால் சுவிஸ் வரிக் கணக்கு CHF இல் தாக்கல் செய்யப்படுகிறது: அவற்றைப் பயன்படுத்தும் முன் இந்த அறிக்கையை CHF இல் மீண்டும் உருவாக்கவும்.",
