            "author_beneficiary_rewards": "ஆசிரியர் & பயனாளி வெகுமதிகள்",
            "other_income_self_employment_if_regular": "பிற வருமானம் (வழக்கமானதெனில் சுயதொழில்)",
            "split_curation_vs_author_see_below": "பிரிப்பு: தொகுப்பு மற்றும் ஆசிரியர் (கீழே காண்க)",
            "claim_timing_merges_author_and_curation": "பெறும் நேர முறை ஆசிரியர், தொகுப்பு வெகுமதிகளை ஒன்றிணைக்கிறது; சேரும் நேர முறை அவற்றைத் தனித்தனியாக அறிக்கையிடும்",
