            "not_declared_tax_exempt_private_gain": "அறிவிக்கப்படவில்லை (வரி விலக்குள்ள தனிப்பட்ட ஆதாயம்)",
            "kept_as_a_record_losses_are_not": "பதிவாக வைக்கப்படுகிறது; நட்டங்களும் கழிக்கத்தக்கவை அல்ல",
            "nothing_to_declare_from_this_account": "இக்காலத்திற்கு இந்தக் கணக்கிலிருந்து அறிவிக்க எதுவும் இல்லை.",
            "author_and_beneficiary_rewards_pay_for": "ஆசிரியர், பயனாளி வெகுமதிகளும் முன்மொழிவுக் கொடுப்பனவுகளும் டோக்கன்களை வைத்திருப்பதற்கு அல்ல, வேலைக்கே வழங்கப்படுகின்றன: அந்தச் செயல்பாடு வழக்கமானதும் ஒழுங்கமைக்கப்பட்டதுமாக இருந்தால், கேன்டன் அதைச் சுயதொழிலாகக் கருதலாம்; அது AHV/AVS பங்களிப்புகளையும் கொண்டுவரும். தொகுப்பு வெகுமதிகளும் சேமிப்பு வட்டியும், ஸ்டேக்கிங் வெகுமதிகளைப் போல, உங்கள் ஸ்டேக் மீதான வருவாய்.",
            "br_annex_title": "அதிகார வரம்பு இணைப்பு — பிரேசில் (IN RFB 1888)",
            "br_annex_note": "பிரேசில் அல்லாத தளங்களிலான செயல்பாட்டிற்கான R$30,000 சுய-அறிக்கை வரம்புடன் ஒப்பிட்டு, மாதாந்திர மொத்த அகற்றல் விற்றுப்பெற்ற தொகைகள்; வரம்பை மீறிய மாதங்கள் குறிக்கப்படுகின்றன. மொத்த விற்றுப்பெற்ற தொகைகள் அளவின் பதிலியாகக் காட்டப்படுகின்றன — உங்கள் முழு மாதாந்திரச் செயல்பாட்டு அளவைக் கணக்கிடும்போது கையகப்படுத்தல்களையும் சேர்க்கவும்.",
            "br_annex_not_in_brl": "எண்ணிக்கைகள் {{fiat}} இல் உள்ளன; சட்டப்பூர்வ வரம்பு BRL இல் வரையறுக்கப்பட்டுள்ளது — ஒப்பிடும் முன் மாற்றவும் (குறிகள் இடப்படவில்லை).",
            "col_month": "மாதம்",
            "col_gross_proceeds_fiat": "மொத்த விற்றுப்பெற்றது ({{fiat}})",
            "col_r30000_threshold": "R$30,000 வரம்பு",
            "over_report": "மீறியது - அறிக்கையிடவும்",
            "under": "குறைவு",
            "decripto_expands_reporting_from_2026": "DeCripto 2026 முதல் அறிக்கையிடலை விரிவாக்குகிறது — குறிக்கப்பட்ட ஒவ்வொரு மாதத்திற்குமான CSV உருப்படி வரிசைகளை வைத்திருக்கவும்.",
            "in_annex_title": "அதிகார வரம்பு இணைப்பு — இந்தியா (Form 26AS / TDS சமரசம்)",
            "in_annex_note": "மாதந்தோறும் மொத்தப் பிரதிபலன், section 194S TDS குறிக்கும் குறிப்புக்கான 1% உடன் — உங்கள் Form 26AS / AIS இல் உள்ள வரவுகளுடன் சமரசம் செய்யவும். P2P மற்றும் வெளிநாட்டுத் தளங்களில் வாங்குபவரே பிடித்தம் செய்து செலுத்த வேண்டும்; ஆண்டு வரம்புகள் Rs 50,000 / Rs 10,000 பொருந்தும்.",
            "in_annex_not_in_inr": "எண்ணிக்கைகள் {{fiat}} இல் உள்ளன; சட்டப்பூர்வ வரம்புகள் INR இல் வரையறுக்கப்பட்டுள்ளன.",
            "col_transfers": "பரிமாற்றங்கள்",
            "col_gross_consideration_fiat": "மொத்தப் பிரதிபலன் ({{fiat}})",
            "col_indicative_tds_fiat": "குறிப்புக்கான TDS 1% ({{fiat}})",
            "id_annex_title": "அதிகார வரம்பு இணைப்பு — இந்தோனேசியா (PMK 50/2025 இறுதி வரி)",
            "id_annex_note": "வெளிநாட்டுத் தளங்கள் வழியான பரிவர்த்தனைகளுக்கான குறிப்புக்கான 1% இறுதி வருமான வரியுடன், மாதாந்திர மொத்த அகற்றல் மதிப்பு (வசூலிப்பவர் நியமிக்கப்படாத இடங்களில் விற்பவரே சுய மதிப்பீடு செய்வார்) — சட்டப்பூர்வ அடிப்படை ஆதாயம் அல்ல, மொத்தப் பரிவர்த்தனை மதிப்பே. பதிவுசெய்யப்பட்ட உள்நாட்டுத் தளங்கள் அதற்குப் பதிலாக 0.21% பிடித்தம் செய்கின்றன.",
            "id_annex_not_in_idr": "எண்ணிக்கைகள் {{fiat}} இல் உள்ளன; சட்டப்பூர்வ அடிப்படை IDR இல் மதிப்பிடப்படுகிறது — தாக்கல் செய்யும் முன் மாற்றவும்.",
            "col_gross_value_fiat": "மொத்த மதிப்பு ({{fiat}})",
            "col_indicative_1_fiat": "குறிப்புக்கான 1% ({{fiat}})",
            "uk_annex_title": "அதிகார வரம்பு இணைப்பு — ஐக்கிய இராச்சியம் (பங்குப் பொருத்தல்)",
            "uk_annex_note": "HMRC இன் வரிசைமுறையின் கீழ் (TCGA 1992 s.105 / s.106A) அகற்றல் அளவு எவ்வாறு பொருத்தப்பட்டது: முதலில் அதே நாள் கையகப்படுத்தல்கள், பின்னர் அடுத்த 30 நாட்களிலான கையகப்படுத்தல்கள், பின்னர் section-104 தொகுப்பு.",
            "col_matching_rule": "பொருத்தல் விதி",
            "same_day_s105": "அதே நாள் (s.105)",
            "thirty_day_bed_and_breakfast_s106a": "30 நாள் bed & breakfast (s.106A)",
            "section_104_pool": "Section-104 தொகுப்பு",
            "decision_support_document_not_a_filed": "ஆன்-செயின் தரவிலிருந்து உருவாக்கப்பட்ட முடிவு-ஆதரவு ஆவணம் — தாக்கல் செய்யப்பட்ட வரிக் கணக்கு அல்ல. எண்ணிக்கைகள் தகுதிவாய்ந்த ஆலோசகரால் மதிப்பாய்வு செய்யப்பட்டு உறுதிப்படுத்தப்பட வேண்டும்.",
