            "category_commercial": "வணிகம்",
            "if_granted_enables_commercial_sub_rights": "வழங்கப்பட்டால், கீழேயுள்ள வணிகத் துணை உரிமைகளை இயக்கும்",
            "use_in_social_media_or_advertising_campaigns": "சமூக ஊடகங்கள் அல்லது விளம்பரப் பிரச்சாரங்களில் பயன்படுத்துதல்",
            "print_on_physical_goods_t_shirts_posters": "பௌதிகப் பொருட்களில் அச்சிடுதல் (டி-சர்ட்கள், சுவரொட்டிகள் போன்றவை)",
            "license_to_third_parties_stock_sites_etc": "மூன்றாம் தரப்பினருக்கு உரிமம் வழங்குதல் (stock தளங்கள் போன்றவை)",
            "modify_or_adapt_the_artwork": "கலைப்படைப்பை மாற்றியமைத்தல் அல்லது தழுவுதல்",
            "category_creative": "படைப்பு",
            "with_respect_to_the_authors_moral_rights": "ஆசிரியரின் தார்மீக உரிமைகளை மதித்து",
            "create_public_derivative_works_or_remixes": "பொது வழிப்படைப்புகள் அல்லது ரீமிக்ஸ்களை உருவாக்குதல்",
            "mint_the_artwork_or_derivatives_into_new": "கலைப்படைப்பையோ வழிப்படைப்புகளையோ புதிய NFT-களாக மின்ட் செய்தல்",
            "use_in_virtual_environments_or_metaverses": "மெய்நிகர் சூழல்கள் அல்லது மெட்டாவர்ஸ்களில் பயன்படுத்துதல்",
            "category_digital": "டிஜிட்டல்",
            "include_in_digital_games_or_apps": "டிஜிட்டல் விளையாட்டுகள் அல்லது செயலிகளில் சேர்த்தல்",
            "use_in_music_videos_or_films": "இசை வீடியோக்கள் அல்லது திரைப்படங்களில் பயன்படுத்துதல்",
            "category_media": "ஊடகம்",
            "display_in_online_or_offline_exhibitions": "ஆன்லைன் அல்லது ஆஃப்லைன் கண்காட்சிகளில் காட்சிப்படுத்துதல்",
            "category_display": "காட்சி",
            "use_in_educational_materials_or": "கல்விப் பொருட்கள் அல்லது விளக்கக்காட்சிகளில் பயன்படுத்துதல்",
            "category_educational": "கல்வி",
